import{_ as p,r as s,o,c as i,e as t,a as c,s as r}from"./chunks/framework.CXcwiNg-.js";const m=JSON.parse('{"title":"Dropdown Inspector Type - October CMS - 3.x","titleTemplate":false,"description":"Inspector Type","frontmatter":{"subtitle":"Inspector Type","shortname":"Dropdown"},"headers":[{"level":2,"title":"Dynamic Options","slug":"dynamic-options","link":"#dynamic-options","children":[]},{"level":2,"title":"Page List Properties","slug":"page-list-properties","link":"#page-list-properties","children":[]}],"relativePath":"3.x/element/inspector/type-dropdown.md","filePath":"3.x/element/inspector/type-dropdown.md"}'),l={name:"3.x/element/inspector/type-dropdown.md"};function u(g,n,d,k,h,f){const a=s("pre-heading"),e=s("post-heading");return o(),i("div",null,[t(a),n[0]||(n[0]=c("h1",null,"Dropdown Inspector Type",-1)),t(e),n[1]||(n[1]=r(`<p>The <code>dropdown</code> inspector type is used to make a single from a set of predefined options. The option list for dropdown and set properties can be static or dynamic. Static options are defined with the <code>options</code> element of the property definition.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">defineProperties</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;unit&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Unit&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;type&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;dropdown&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;default&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;imperial&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;placeholder&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Select units&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;options&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;metric&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Metric&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;imperial&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Imperial&#39;</span><span class="token punctuation">]</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The generated output is a string value corresponding to the selected option, for example:</p><div class="language-json extra-class"><pre class="language-json"><code><span class="token property">&quot;unit&quot;</span><span class="token operator">:</span> <span class="token string">&quot;metric&quot;</span>
</code></pre></div><p>The following <a href="./../inspector-types.html">configuration values</a> are commonly used.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>title</strong></td><td>title for the property.</td></tr><tr><td><strong>description</strong></td><td>a brief description of the property, optional.</td></tr><tr><td><strong>default</strong></td><td>specifies a default string value, optional.</td></tr><tr><td><strong>options</strong></td><td>array of options for dropdown properties, optional if defining a <code>get*PropertyName*Options</code> method.</td></tr></tbody></table></div><h2 id="dynamic-options"><a href="#dynamic-options" class="header-anchor">#</a> Dynamic Options</h2><p>The list of options could be fetched dynamically from the server when the Inspector is displayed. If the <code>options</code> parameter is omitted in a dropdown or set property definition the option list is considered dynamic. The component class must define a method returning the option list. The method should have a name in the following format: <code>get*PropertyName*Options</code>, where <strong>Property</strong> is the property name, for example: <code>getCountryOptions</code>. The method returns an array of options with the option values as keys and option labels as values. Example of a dynamic dropdown list definition.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">defineProperties</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;country&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Country&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;type&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;dropdown&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;default&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;us&#39;</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">getCountryOptions</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;us&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;United states&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;ca&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Canada&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Dynamic dropdown and set lists can depend on other properties. For example, the state list could depend on the selected country. The dependencies are declared with the <code>depends</code> parameter in the property definition. The next example defines two dynamic dropdown properties and the state list depends on the country.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">defineProperties</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;country&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Country&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;type&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;dropdown&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;default&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;us&#39;</span>
        <span class="token punctuation">]</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;state&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;State&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;type&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;dropdown&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;default&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;dc&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;depends&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;country&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;placeholder&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Select a state&#39;</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>In order to load the state list you should know what country is currently selected in the Inspector. The Inspector POSTs all property values to the <code>getPropertyOptions</code> handler, so you can do the following.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">getStateOptions</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// Load the country property value from POST</span>
    <span class="token variable">$countryCode</span> <span class="token operator">=</span> <span class="token function">post</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;country&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token variable">$states</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;ca&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;ab&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Alberta&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;bc&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;British columbia&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;us&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;al&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Alabama&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;ak&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Alaska&#39;</span><span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">return</span> <span class="token variable">$states</span><span class="token punctuation">[</span><span class="token variable">$countryCode</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="page-list-properties"><a href="#page-list-properties" class="header-anchor">#</a> Page List Properties</h2><p>Sometimes components need to create links to the website pages. For example, the blog post list contains links to the blog post details page. In this case the component should know the post details page file name (then it can use the <a href="./../../markup/filter/page.html">page Twig filter</a>). October includes a helper for creating dynamic dropdown page lists. The next example defines the postPage property which displays a list of pages:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">defineProperties</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;postPage&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Post page&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;type&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;dropdown&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;default&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;blog/post&#39;</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">getPostPageOptions</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Page</span><span class="token operator">::</span><span class="token function">sortBy</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;baseFileName&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">lists</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;baseFileName&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;baseFileName&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div>`,16))])}const q=p(l,[["render",u]]);export{m as __pageData,q as default};
